"""match_profile against golden output generated by the TS version (tests/fixtures/golden.ts)."""

import json
from pathlib import Path
from typing import Any

import pytest

from cv_tailor_py.agent import match_profile
from cv_tailor_py.cli import load_profile
from cv_tailor_py.models import ParsedJD, Role

ROOT = Path(__file__).resolve().parent.parent
FIXTURES = ROOT / "tests" / "fixtures"
GOLDEN: dict[str, Any] = json.loads((FIXTURES / "golden.json").read_text())["match"]
CASES: list[dict[str, Any]] = json.loads((FIXTURES / "match_cases.json").read_text())
TIEBREAK = load_profile(FIXTURES / "profile_tiebreak.json")


def _jd(required: list[str], nice: list[str] | None = None) -> ParsedJD:
    return ParsedJD(role="", seniority="", required_skills=required, nice_to_have=nice or [])


def _ids(roles: list[Role]) -> list[list[str]]:
    return [[a.id for a in r.achievements] for r in roles]


@pytest.mark.parametrize("case", CASES, ids=lambda c: c["id"])
def test_match_profile_matches_ts(case: dict[str, Any]) -> None:
    profile = load_profile(ROOT / case["profile"])
    jd = ParsedJD.model_validate(case["jd"])

    roles = match_profile(profile, jd)

    assert [r.model_dump() for r in roles] == GOLDEN[case["id"]]["roles"]


def test_tie_break_keeps_profile_order_and_cuts_at_five() -> None:
    roles = match_profile(TIEBREAK, _jd(["React", "typescript"], ["GO"]))

    # Scores: t1=1 t2=2 t3=1 t4=0 t5=2 t6=1 t7=1. Ties keep profile order; t7 falls past the cut.
    # z2 lists React twice and scores 2 (duplicates count, as in TS). Empty roles stay empty.
    assert _ids(roles) == [["t2", "t5", "t1", "t3", "t6"], ["z2", "z1"], []]


def test_per_role_limit() -> None:
    roles = match_profile(TIEBREAK, _jd(["React"]), per_role=2)
    assert _ids(roles) == [["t1", "t2"], ["z2", "z1"], []]


def test_no_overlap_keeps_original_order() -> None:
    roles = match_profile(TIEBREAK, _jd(["Spark"]))
    assert _ids(roles) == [["t1", "t2", "t3", "t4", "t5"], ["z1", "z2"], []]


def test_role_fields_preserved_and_profile_untouched() -> None:
    before = TIEBREAK.model_dump()

    roles = match_profile(TIEBREAK, _jd(["React"]))

    assert TIEBREAK.model_dump() == before
    for got, orig in zip(roles, TIEBREAK.roles, strict=True):
        assert got.model_dump(exclude={"achievements"}) == orig.model_dump(exclude={"achievements"})


def test_match_profile_logs_function_span(spans: Any) -> None:
    match_profile(TIEBREAK, _jd(["React"]))

    (span,) = [s for s in spans.pop() if s["span_attributes"]["name"] == "match_profile"]
    assert span["span_attributes"]["type"] == "function"
    assert [a["id"] for a in span["output"][0]["achievements"]] == ["t1", "t2", "t7", "t3", "t4"]
